import '../domain/analytics.dart';

class LocalAnalyticsEngine {
  const LocalAnalyticsEngine();

  AnalyticsReport build(AnalyticsSnapshot s) {
    final study=_trend(s.studyMinutes7d.toDouble(),s.studyMinutesPrev7d.toDouble(),20);
    final quiz=s.quizAccuracy7d!=null&&s.quizAccuracyPrev7d!=null?_trend(s.quizAccuracy7d!,s.quizAccuracyPrev7d!,.04):null;
    var momentumScore=_trendScore(study.direction)+(quiz==null?0:_trendScore(quiz.direction));
    final deltas=s.courses.map((e)=>e.masteryDelta7d).whereType<double>().toList();
    if(deltas.isNotEmpty){final avg=deltas.reduce((a,b)=>a+b)/deltas.length; momentumScore+=avg>.03?1:avg<-.03?-1:0;}
    final evidence=s.activeDays7d>=5?AnalyticsEvidence.strong:s.activeDays7d>=3?AnalyticsEvidence.moderate:AnalyticsEvidence.limited;
    final momentum=evidence==AnalyticsEvidence.limited?AnalyticsTrend.stable:momentumScore>0?AnalyticsTrend.improving:momentumScore<0?AnalyticsTrend.declining:AnalyticsTrend.stable;
    final insights=s.courses.map(_insight).toList()..sort((a,b){final r={AnalyticsRisk.high:0,AnalyticsRisk.medium:1,AnalyticsRisk.low:2}; final c=r[a.risk]!.compareTo(r[b.risk]!); if(c!=0)return c; return (a.readiness??101).compareTo(b.readiness??101);});
    final recs=_recommendations(s);
    return AnalyticsReport(generatedAt:s.generatedAt,momentum:momentum,evidence:evidence,studyTime:study,quizAccuracy:quiz,activeDays7d:s.activeDays7d,streakDays:s.streakDays,planAdherence7d:s.planAdherence7d,activity14d:s.activity14d,courseInsights:insights,recommendations:recs,explanation:'Indicateurs basés sur tes activités récentes. Ils décrivent ta progression ; ils ne prédisent pas ta note ni ta réussite.');
  }

  TrendMetric _trend(double current,double previous,double epsilon){final d=current-previous; final direction=d>epsilon?AnalyticsTrend.improving:d<-epsilon?AnalyticsTrend.declining:AnalyticsTrend.stable; return TrendMetric(current,previous,d,direction);}
  int _trendScore(AnalyticsTrend t)=>t==AnalyticsTrend.improving?1:t==AnalyticsTrend.declining?-1:0;
  int? _readiness(CourseAnalyticsSignal c){final values=<({double v,double w})>[]; if(c.coverage!=null)values.add((v:c.coverage!,w:.30)); if(c.quizMastery!=null)values.add((v:c.quizMastery!,w:.40)); if(c.flashcardMastery!=null)values.add((v:c.flashcardMastery!,w:.15)); if(c.weaknessRecovery!=null)values.add((v:c.weaknessRecovery!,w:.15)); if(values.isEmpty)return null; final w=values.fold(0.0,(a,b)=>a+b.w); return (values.fold(0.0,(a,b)=>a+b.v*b.w)/w*100).round();}
  CourseInsight _insight(CourseAnalyticsSignal c){final readiness=c.nextAssessmentReadiness??_readiness(c); AnalyticsRisk risk; String reason; final urgent=c.daysToNextAssessment!=null&&c.daysToNextAssessment!<=3; if(urgent&&(readiness??0)<60){risk=AnalyticsRisk.high;reason='Évaluation proche avec préparation encore insuffisante.';}else if(c.openErrors>=8||(readiness!=null&&readiness<45)){risk=AnalyticsRisk.high;reason='Plusieurs difficultés restent ouvertes dans ce cours.';}else if(c.overdueFlashcards>=12||(readiness!=null&&readiness<70)){risk=AnalyticsRisk.medium;reason='Une révision ciblée peut consolider ce cours.';}else{risk=AnalyticsRisk.low;reason='Progression régulière ; maintenir le rythme.';} final d=c.masteryDelta7d==null||c.masteryDelta7d!.abs()<.03?AnalyticsTrend.stable:c.masteryDelta7d!>0?AnalyticsTrend.improving:AnalyticsTrend.declining; return CourseInsight(courseId:c.courseId,title:c.title,readiness:readiness,risk:risk,focusReason:reason,direction:d,coverage:c.coverage,quizMastery:c.quizMastery,flashcardMastery:c.flashcardMastery,weaknessRecovery:c.weaknessRecovery,openErrors:c.openErrors,overdueFlashcards:c.overdueFlashcards,daysToNextAssessment:c.daysToNextAssessment,studyMinutes7d:c.studyMinutes7d);}

  List<StudyRecommendation> _recommendations(AnalyticsSnapshot s){final all=<StudyRecommendation>[]; for(final c in s.courses){final readiness=c.nextAssessmentReadiness??_readiness(c); if(c.daysToNextAssessment!=null&&c.daysToNextAssessment!<=7){final gap=(80-(readiness??0)).clamp(0,80);final urgency=(8-c.daysToNextAssessment!).clamp(0,8)*8; all.add(StudyRecommendation(id:'assessment:${c.courseId}',kind:RecommendationKind.assessmentFocus,courseId:c.courseId,courseTitle:c.title,title:'Préparer ${c.title}',reason:'Évaluation dans ${c.daysToNextAssessment} jour(s) · préparation ${readiness??0} %.',recommendedMinutes:c.daysToNextAssessment!<=2?45:30,priorityScore:(45+urgency+gap~/2).clamp(0,100).toInt(),deepLink:'/revision'));} if(c.openErrors>0){all.add(StudyRecommendation(id:'errors:${c.courseId}',kind:RecommendationKind.recoverErrors,courseId:c.courseId,courseTitle:c.title,title:'Revoir tes erreurs en ${c.title}',reason:'${c.openErrors} erreur(s) restent à récupérer.',recommendedMinutes:(c.openErrors*3).clamp(10,30).toInt(),priorityScore:(45+c.openErrors*4+(c.daysToNextAssessment!=null&&c.daysToNextAssessment!<=5?15:0)).clamp(0,96).toInt(),deepLink:'/study/${c.courseId}?title=${Uri.encodeComponent(c.title)}'));} if(c.overdueFlashcards>=5){all.add(StudyRecommendation(id:'flashcards:${c.courseId}',kind:RecommendationKind.flashcardReview,courseId:c.courseId,courseTitle:c.title,title:'Rattraper les flashcards de ${c.title}',reason:'${c.overdueFlashcards} carte(s) sont arrivées à échéance.',recommendedMinutes:c.overdueFlashcards.clamp(8,25).toInt(),priorityScore:(35+c.overdueFlashcards*3).clamp(0,88).toInt(),deepLink:'/study/${c.courseId}/flashcards?title=${Uri.encodeComponent(c.title)}'));} if(c.quizMastery!=null&&c.quizMastery!<.65){all.add(StudyRecommendation(id:'quiz:${c.courseId}',kind:RecommendationKind.quizDrill,courseId:c.courseId,courseTitle:c.title,title:'Faire un quiz ciblé en ${c.title}',reason:'Maîtrise quiz actuelle : ${(c.quizMastery!*100).round()} %.',recommendedMinutes:15,priorityScore:(40+((.65-c.quizMastery!)*80).round()).clamp(0,84).toInt(),deepLink:'/study/${c.courseId}/quiz?title=${Uri.encodeComponent(c.title)}'));} if((c.coverage??0)<.55&&c.studyMinutes7d<30){all.add(StudyRecommendation(id:'continue:${c.courseId}',kind:RecommendationKind.continueCourse,courseId:c.courseId,courseTitle:c.title,title:'Continuer ${c.title}',reason:'Le cours reste peu couvert cette semaine.',recommendedMinutes:20,priorityScore:45,deepLink:'/study/${c.courseId}?title=${Uri.encodeComponent(c.title)}'));}}
    if(s.planAdherence7d!=null&&s.planAdherence7d!<.5){all.add(StudyRecommendation(id:'plan:recovery',kind:RecommendationKind.planRecovery,title:'Alléger ton plan de révision',reason:'Tu as réalisé ${(s.planAdherence7d!*100).round()} % du planning récent. Un plan plus réaliste sera plus durable.',recommendedMinutes:5,priorityScore:80,deepLink:'/revision/planning-settings'));}
    all.sort((a,b){final p=b.priorityScore.compareTo(a.priorityScore);return p!=0?p:a.recommendedMinutes.compareTo(b.recommendedMinutes);}); final selected=<StudyRecommendation>[];final count=<String,int>{};for(final r in all){final k=r.courseId??'global';if((count[k]??0)>=2)continue;selected.add(r);count[k]=(count[k]??0)+1;if(selected.length==5)break;} return selected;
  }
}
